     old=ratio
    # Pair-cost monotonicity for the perturbed complete reversed kernel.
    aa=[F(0)]+[es[0][m-1]/es[1][m] for m in range(1,j+1)]
    bb=[es[2][m+1]/es[1][m] for m in range(j)]+[F(0)]
    for m in range(2,j+1):
     for n in range(m-1):
